tasks.solution:
class Account:
    def __init__(self, balance):
        self.balance = balance

    def withdraw(self, amount):
        if amount <= self.balance:
            self.balance -= amount
            return True
        return False

def is_palindrome(s):
    clean = s.replace(" ", "").lower()
    return clean == clean[::-1]
